orders = [{"id": 1, "items": ["pen", "ink"]}, {"id": 2, "items": ["paper"]}, {"id": 3, "items": ["pen", "cover", "ink"]}]
prices = {"pen": 2, "ink": 5, "paper": 4}
unknown = set()
for order in orders:
    total = 0
    for item in order["items"]:
        total += prices.get(item, 0)
        if item not in prices:
            unknown.add(item)
    print(f"Order {order['id']}: {total}")
print("Unknown items:", sorted(unknown))

students = [{"name": "Ada", "class_id": 2}, {"name": "Bo", "class_id": 5}, {"name": "Cy", "class_id": 1}]
classes = [{"id": 1, "room": "A1"}, {"id": 2, "room": "B7"}]
missing = 0
for student in students:
    room = "TBC"
    for c in classes:
        if c["id"] == student["class_id"]:
            room = c["room"]
            break
    if room == "TBC":
        missing += 1
    print(f"{student['name']}: {room}")
print("Missing rooms:", missing)

